1	// Приёмочные тесты «Мин» через тестовую платформу (games/mines/spec.md, SC-1…SC-13).
2	// Поведение проверяется снаружи: ответы startRound/action/open, баланс, журнал транзакций, коды ошибок.
3	import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
4	import game from '../server/index.ts';
5	import { createTestPlatform, fixedRng } from '../../../platform/testkit/index.ts';
6	
7	/** Код ошибки, которую бросает fn; если fn не бросила — тест падает. */
8	function codeOf(fn: () => unknown): string {
9	  try {
10	    const v = fn();
11	    throw new Error(`ожидалась ошибка, а вызов вернул ${JSON.stringify(v)}`);
12	  } catch (e: any) {
13	    if (e instanceof Error && e.message.startsWith('ожидалась ошибка')) throw e;
14	    return e?.code;
15	  }
16	}
17	
18	function platform(rng: number[], startBalance = 100) {
19	  return createTestPlatform({ games: [game], rng: fixedRng(rng), startBalance });
20	}
21	
22	const R = (cell: unknown) => ({ type: 'reveal', cell });
23	const CO = { type: 'cashout' };
24	
25	/** Журнал транзакций в виде [type, amount, balanceAfter]. */
26	const txList = (p: ReturnType<typeof platform>) => p.transactions().map((t) => [t.type, t.amount, t.balanceAfter]);
27	
28	/** Поля, которые не должны появляться во view открытого раунда. */
29	function expectHidden(view: unknown): void {
30	  expect(view).not.toHaveProperty('mines');
31	  expect(view).not.toHaveProperty('hit');
32	  expect(view).not.toHaveProperty('outcome');
33	}
34	
35	describe('Мины: раунды через платформу', () => {
36	  beforeEach(() => {
37	    // Исход определяется только переданным rng (spec: «Math.random не используется»).
38	    vi.spyOn(Math, 'random').mockImplementation(() => {
39	      throw new Error('Math.random запрещён в игре');
40	    });
41	  });
42	  afterEach(() => {
43	    vi.restoreAllMocks();
44	  });
45	
46	  it('SC-1: три безопасные клетки и cashout — выплата 2 × 1.46 = 2.92', () => {
47	    const p = platform([0.5, 0.75, 0.25]); // мины 7, 12, 19
48	    const r0 = p.startRound('mines', 2, {});
49	    expect(r0.gameId).toBe('mines');
50	    expect(r0.status).toBe('open');
51	    expect(r0.bet).toBe(2);
52	    expect(r0.payout).toBeNull();
53	    expect(r0.balance).toBe(98);
54	    expect(r0.view).toEqual({ mineCount: 3, revealed: [], multiplier: 1, nextMultiplier: 1.11 });
55	    expect(p.balance()).toBe(98);
56	    expect(txList(p)).toEqual([['bet', 2, 98]]);
57	
58	    const r1 = p.action(r0.roundId, R(0));
59	    expect(r1.roundId).toBe(r0.roundId);
60	    expect(r1.status).toBe('open');
61	    expect(r1.payout).toBeNull();
62	    expect(r1.balance).toBe(98);
63	    expect(r1.view).toEqual({ mineCount: 3, revealed: [0], multiplier: 1.11, nextMultiplier: 1.27 });
64	
65	    const r2 = p.action(r0.roundId, R(6));
66	    expect(r2.status).toBe('open');
67	    expect(r2.view).toEqual({ mineCount: 3, revealed: [0, 6], multiplier: 1.27, nextMultiplier: 1.46 });
68	
69	    const r3 = p.action(r0.roundId, R(24));
70	    expect(r3.status).toBe('open');
71	    expect(r3.balance).toBe(98);
72	    expect(r3.view).toEqual({ mineCount: 3, revealed: [0, 6, 24], multiplier: 1.46, nextMultiplier: 1.69 });
73	    expect(p.transactions()).toHaveLength(1);
74	
75	    const r4 = p.action(r0.roundId, CO);
76	    expect(r4.status).toBe('closed');
77	    expect(r4.payout).toBe(2.92);
78	    expect(r4.balance).toBe(100.92);
79	    expect(r4.view).toEqual({
80	      mineCount: 3,
81	      revealed: [0, 6, 24],
82	      multiplier: 1.46,
83	      nextMultiplier: null,
84	      mines: [7, 12, 19],
85	      hit: null,
86	      outcome: 'cashout',
87	    });
88	    expect(p.balance()).toBe(100.92);
89	    const txs = p.transactions();
90	    expect(txs).toHaveLength(2);
91	    expect(txs[0]).toMatchObject({ type: 'bet', roundId: r0.roundId, amount: 2, balanceAfter: 98 });
92	    expect(txs[1]).toMatchObject({ type: 'payout', roundId: r0.roundId, amount: 2.92, balanceAfter: 100.92 });
93	    expect(p.open('mines').activeRound).toBeNull();
94	  });
