96	  it('SC-1: множитель растёт по таблице M(1)…M(5), cashout при k = 5 платит 1.98', () => {
97	    const p = platform([0.5, 0.75, 0.25]); // мины 7, 12, 19
98	    const r = p.startRound('mines', 1, {});
99	    const expected: Array<[number, number, number]> = [
100	      [0, 1.11, 1.27],
101	      [1, 1.27, 1.46],
102	      [2, 1.46, 1.69],
103	      [3, 1.69, 1.98],
104	      [4, 1.98, 2.33],
105	    ];
106	    for (const [cell, m, next] of expected) {
107	      const v = p.action(r.roundId, R(cell));
108	      expect(v.status).toBe('open');
109	      expect(v.view).toMatchObject({ multiplier: m, nextMultiplier: next });
110	      expectHidden(v.view);
111	    }
112	    const out = p.action(r.roundId, CO);
113	    expect(out.payout).toBe(1.98);
114	    expect(out.balance).toBe(100.98);
115	  });
116	
117	  it('SC-2: мина после безопасной клетки — выплата 0, мины раскрыты', () => {
118	    const p = platform([0.5, 0.75, 0.25]);
119	    const r0 = p.startRound('mines', 5, {});
120	    expect(r0.balance).toBe(95);
121	    const r1 = p.action(r0.roundId, R(0));
122	    expect(r1.status).toBe('open');
123	    expect(r1.balance).toBe(95);
124	
125	    const r2 = p.action(r0.roundId, R(12));
126	    expect(r2.status).toBe('closed');
127	    expect(r2.payout).toBe(0);
128	    expect(r2.balance).toBe(95);
129	    expect(r2.view).toEqual({
130	      mineCount: 3,
131	      revealed: [0],
132	      multiplier: 1.11,
133	      nextMultiplier: null,
134	      mines: [7, 12, 19],
135	      hit: 12,
136	      outcome: 'mine',
137	    });
138	    expect(p.balance()).toBe(95);
139	    expect(txList(p)).toEqual([
140	      ['bet', 5, 95],
141	      ['payout', 0, 95],
142	    ]);
143	    expect(p.open('mines').activeRound).toBeNull();
144	  });
