146	  it('SC-3: мина первым ходом — проигрыш, revealed пуст', () => {
147	    const p = platform([0.5, 0.75, 0.25]);
148	    const r0 = p.startRound('mines', 1, {});
149	    const r = p.action(r0.roundId, R(19));
150	    expect(r.status).toBe('closed');
151	    expect(r.payout).toBe(0);
152	    expect(r.balance).toBe(99);
153	    expect(r.view).toEqual({
154	      mineCount: 3,
155	      revealed: [],
156	      multiplier: 1,
157	      nextMultiplier: null,
158	      mines: [7, 12, 19],
159	      hit: 19,
160	      outcome: 'mine',
161	    });
162	    expect(txList(p)).toEqual([
163	      ['bet', 1, 99],
164	      ['payout', 0, 99],
