168	  it('SC-3: каждая из трёх мин (7, 12, 19) проигрывает, соседние клетки безопасны', () => {
169	    for (const mine of [7, 12, 19]) {
170	      const p = platform([0.5, 0.75, 0.25]);
171	      const r0 = p.startRound('mines', 1, {});
172	      const r = p.action(r0.roundId, R(mine));
173	      expect(r.status, `клетка ${mine}`).toBe('closed');
174	      expect(r.payout).toBe(0);
175	      expect(r.view).toMatchObject({ hit: mine, outcome: 'mine', mines: [7, 12, 19] });
176	      expect(p.balance()).toBe(99);
177	    }
178	    // Соседи мин и «перепутанные» индексы (до сортировки c[0..2] = 12, 19, 7; j = 12, 19, 7) — безопасны.
179	    const p = platform([0.5, 0.75, 0.25]);
180	    const r0 = p.startRound('mines', 1, {});
181	    const safe = [6, 8, 11, 13, 18, 20, 2, 17];
182	    safe.forEach((cell, i) => {
183	      const v = p.action(r0.roundId, R(cell));
184	      expect(v.status, `клетка ${cell}`).toBe('open');
185	      expect((v.view as any).revealed).toEqual(safe.slice(0, i + 1));
186	    });
187	  });
