189	  it('SC-4: границы rng — 0, 0, 0 даёт мины 0, 1, 2; 0.9999 ×3 даёт мины 0, 1, 24', () => {
190	    const p = platform([0, 0, 0, 0.9999, 0.9999, 0.9999]);
191	
192	    const a = p.startRound('mines', 1, {});
193	    expect(a.balance).toBe(99);
194	    const a1 = p.action(a.roundId, R(3));
195	    expect(a1.status).toBe('open');
