197	    const a2 = p.action(a.roundId, R(2));
198	    expect(a2.status).toBe('closed');
199	    expect(a2.payout).toBe(0);
200	    expect(a2.balance).toBe(99);
201	    expect(a2.view).toEqual({
202	      mineCount: 3,
203	      revealed: [3],
204	      multiplier: 1.11,
205	      nextMultiplier: null,
206	      mines: [0, 1, 2],
207	      hit: 2,
208	      outcome: 'mine',
209	    });
210	
211	    const b = p.startRound('mines', 1, {});
212	    expect(b.status).toBe('open');
