216	    expect(b1.view).toMatchObject({ revealed: [2], multiplier: 1.11 });
217	    const b2 = p.action(b.roundId, R(23));
218	    expect(b2.status).toBe('open');
219	    expect(b2.view).toEqual({ mineCount: 3, revealed: [2, 23], multiplier: 1.27, nextMultiplier: 1.46 });
220	    const b3 = p.action(b.roundId, R(24));
221	    expect(b3.status).toBe('closed');
222	    expect(b3.payout).toBe(0);
223	    expect(b3.balance).toBe(98);
224	    expect(b3.view).toEqual({
225	      mineCount: 3,
226	      revealed: [2, 23],
227	      multiplier: 1.27,
228	      nextMultiplier: null,
229	      mines: [0, 1, 24],
230	      hit: 24,
231	      outcome: 'mine',
232	    });
233	
234	    expect(txList(p)).toEqual([
235	      ['bet', 1, 99],
236	      ['payout', 0, 99],
237	      ['bet', 1, 98],
238	      ['payout', 0, 98],
239	    ]);
