242	  it('SC-5: открыты все 22 безопасные клетки — раунд закрывается сам с выплатой 1 × 2254', () => {
243	    const p = platform([0, 0, 0]); // мины 0, 1, 2
244	    const r0 = p.startRound('mines', 1, {});
245	    let last = r0;
246	    for (let cell = 3; cell <= 23; cell++) {
247	      last = p.action(r0.roundId, R(cell));
248	      expect(last.status, `после клетки ${cell}`).toBe('open');
249	      expect(last.payout).toBeNull();
250	      expectHidden(last.view);
251	    }
252	    expect(last.view).toEqual({
253	      mineCount: 3,
254	      revealed: Array.from({ length: 21 }, (_, i) => i + 3),
255	      multiplier: 563.5,
256	      nextMultiplier: 2254,
257	    });
258	    expect(last.balance).toBe(99);
259	    expect(p.transactions()).toHaveLength(1);
260	
261	    const fin = p.action(r0.roundId, R(24));
262	    expect(fin.status).toBe('closed');
263	    expect(fin.payout).toBe(2254);
264	    expect(fin.balance).toBe(2353);
265	    expect(fin.view).toEqual({
266	      mineCount: 3,
267	      revealed: Array.from({ length: 22 }, (_, i) => i + 3),
268	      multiplier: 2254,
269	      nextMultiplier: null,
270	      mines: [0, 1, 2],
271	      hit: null,
272	      outcome: 'cleared',
273	    });
274	    expect(p.balance()).toBe(2353);
275	    expect(txList(p)).toEqual([
276	      ['bet', 1, 99],
277	      ['payout', 2254, 2353],
278	    ]);
279	    expect(p.open('mines').activeRound).toBeNull();
280	    expect(codeOf(() => p.action(r0.roundId, CO))).toBe('ROUND_CLOSED');
