283	  it('SC-5: cashout на 21-й клетке платит M(21) = 563.5', () => {
284	    const p = platform([0, 0, 0]);
285	    const r0 = p.startRound('mines', 2, {});
286	    for (let cell = 3; cell <= 23; cell++) p.action(r0.roundId, R(cell));
287	    const out = p.action(r0.roundId, CO);
