1	// @vitest-environment happy-dom
2	// Интерфейс «Мин» (games/mines/spec.md, SC-15): ui/index.html с подменённым window.PlatformSDK.
3	// Внешний /sdk.js не загружается; инлайновые скрипты страницы выполняются в глобальной области, как обычный <script>.
4	import { readFileSync } from 'node:fs';
5	import { dirname, resolve } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	import { describe, expect, it, vi } from 'vitest';
8	
9	// Строка import.meta.url, а не new URL(): в happy-dom глобальный URL принадлежит окну, а не Node.
10	const HTML_PATH = resolve(dirname(fileURLToPath(import.meta.url)), '../ui/index.html');
11	
12	/** Ждёт выполнения условия, прокручивая очередь задач. */
13	async function waitFor(cond: () => boolean, what: string, timeoutMs = 3000): Promise<void> {
14	  const started = Date.now();
15	  for (;;) {
16	    let ok = false;
17	    try {
18	      ok = cond();
19	    } catch {
20	      ok = false;
21	    }
22	    if (ok) return;
23	    if (Date.now() - started > timeoutMs) throw new Error(`не дождались: ${what}`);
24	    await new Promise((r) => setTimeout(r, 5));
25	  }
26	}
27	
28	const $ = (id: string): HTMLElement => {
29	  const el = document.querySelector(`[data-testid="${id}"]`) as HTMLElement | null;
30	  if (!el) throw new Error(`нет элемента data-testid="${id}"`);
31	  return el;
32	};
33	
34	/** Первое число в тексте элемента (запятая как десятичный разделитель допускается). */
35	const numberIn = (id: string): number => {
36	  const m = ($(id).textContent ?? '').replace(/\s/g, '').replace(',', '.').match(/-?\d+(\.\d+)?/);
37	  return m ? Number(m[0]) : NaN;
38	};
39	
40	const isDisabled = (el: HTMLElement): boolean =>
41	  (el as HTMLButtonElement).disabled === true || el.getAttribute('aria-disabled') === 'true';
42	
43	const state = () => $('game').getAttribute('data-state');
44	const cellState = (i: number) => $(`cell-${i}`).getAttribute('data-cell-state');
45	
46	// Слушатели, которые страница повесила на document/window: снимаются перед повторной «загрузкой»,
47	// чтобы скрипт прошлой загрузки не реагировал на события новой.
48	const tracked: Array<{ target: EventTarget; type: string; fn: any; opts: any }> = [];
49	let patched = false;
50	function trackListeners(): void {
51	  if (patched) return;
52	  patched = true;
53	  const g = globalThis as any;
54	  for (const target of [g.document, g.window] as EventTarget[]) {
55	    const orig = target.addEventListener.bind(target);
56	    (target as any).addEventListener = (type: string, fn: any, opts?: any) => {
57	      tracked.push({ target, type, fn, opts });
58	      return orig(type, fn, opts);
59	    };
60	  }
61	}
62	function dropListeners(): void {
63	  for (const l of tracked.splice(0)) l.target.removeEventListener(l.type, l.fn, l.opts);
64	}
65	
66	/** «Открывает» страницу: разметка без <script>, затем подмена SDK, затем инлайновые скрипты. */
67	function loadPage(sdk: unknown): void {
68	  trackListeners();
69	  dropListeners();
70	  const html = readFileSync(HTML_PATH, 'utf8');
71	  const scripts: string[] = [];
72	  const stripped = html.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi, (_m, attrs: string, code: string) => {
73	    if (!/\bsrc\s*=/.test(attrs) && code.trim()) scripts.push(code);
74	    return '';
75	  });
