    it('SC-20: ROUND_NOT_FOUND — повторный open() без раунда → idle', async () => {
      const sdk = sdkWith('ROUND_NOT_FOUND', { gameId: 'mines', balance: 98, limits: { min: 1, max: 10 }, activeRound: null });
      await loadPlaying(sdk);

      $('cell-6').click();
