    it('SC-20: INVALID_ACTION — только код в error, open() повторно не вызывается, состояние не меняется', async () => {
      const sdk = sdkWith('INVALID_ACTION', { gameId: 'mines', balance: 0, limits: { min: 1, max: 10 }, activeRound: null });
