      expect(textOf('cashout')).toBe('Забрать');
      expect(isDisabled($('cashout'))).toBe(true);
      expect(isDisabled(minesSelect())).toBe(false);
      // Страница не перезагружалась: тот же корневой элемент и глобальная метка.
